// Each yields every entity that currently has all 10 components
// (entities with additional components also match, unless a filter excludes
// one of them).
//
// Writing through the yielded pointers, or a Set on an entity that already
// has every component, is safe during iteration. A structural change
// (creating or deleting an entity, or an add/remove) panics with
// "ecs: query invalidated by world mutation" once the loop body that caused
// it returns true to continue; breaking out of the loop is always safe.
//
// Cost: 0 allocations per loop in the common case. A nested iteration of
// the same View10 (the same View10 used inside its own Each loop)
// allocates once: the per-archetype column buffer below is already in use
// by the outer call.
//
// Panics with "ecs: not bound to a world" if View10 is the zero value.
func (v View10[T1, T2, T3, T4, T5, T6, T7, T8, T9, T10]) Each() iter.Seq2[Entity, Components10[T1, T2, T3, T4, T5, T6, T7, T8, T9, T10]] {
	st := v.state
	if st == nil {
		panicNotBound()
	}
	return func(yield func(Entity, Components10[T1, T2, T3, T4, T5, T6, T7, T8, T9, T10]) bool) {
		st.scan()
		cols := st.cols
		if st.iterating {
			cols = make([]storage.Column, len(st.ids))
		} else {
			st.iterating = true
			defer func() { st.iterating = false }()
		}
		rev := st.world.revision
		for _, arch := range st.matched {
			n := arch.Len()
			if n == 0 {
				continue
			}
			cols[0] = arch.Column(arch.ColumnIndex(st.ids[0]))
			cols[1] = arch.Column(arch.ColumnIndex(st.ids[1]))
			cols[2] = arch.Column(arch.ColumnIndex(st.ids[2]))
			cols[3] = arch.Column(arch.ColumnIndex(st.ids[3]))
			cols[4] = arch.Column(arch.ColumnIndex(st.ids[4]))
			cols[5] = arch.Column(arch.ColumnIndex(st.ids[5]))
			cols[6] = arch.Column(arch.ColumnIndex(st.ids[6]))
			cols[7] = arch.Column(arch.ColumnIndex(st.ids[7]))
			cols[8] = arch.Column(arch.ColumnIndex(st.ids[8]))
			cols[9] = arch.Column(arch.ColumnIndex(st.ids[9]))
			colComp1 := cols[0].(*storage.TypedColumn[T1])
			colComp2 := cols[1].(*storage.TypedColumn[T2])
			colComp3 := cols[2].(*storage.TypedColumn[T3])
			colComp4 := cols[3].(*storage.TypedColumn[T4])
			colComp5 := cols[4].(*storage.TypedColumn[T5])
			colComp6 := cols[5].(*storage.TypedColumn[T6])
			colComp7 := cols[6].(*storage.TypedColumn[T7])
			colComp8 := cols[7].(*storage.TypedColumn[T8])
			colComp9 := cols[8].(*storage.TypedColumn[T9])
			colComp10 := cols[9].(*storage.TypedColumn[T10])
			for row := range n {
				e := entityFromStorage(arch.Entity(row))
				comp := Components10[T1, T2, T3, T4, T5, T6, T7, T8, T9, T10]{
					Comp1:  colComp1.Ptr(row),
					Comp2:  colComp2.Ptr(row),
					Comp3:  colComp3.Ptr(row),
					Comp4:  colComp4.Ptr(row),
					Comp5:  colComp5.Ptr(row),
					Comp6:  colComp6.Ptr(row),
					Comp7:  colComp7.Ptr(row),
					Comp8:  colComp8.Ptr(row),
					Comp9:  colComp9.Ptr(row),
					Comp10: colComp10.Ptr(row),
				}
				if !yield(e, comp) {
					return
				}
				if st.world.revision != rev {
					panicQueryInvalidated()
				}
			}
		}
	}
}

// Components11 holds pointers to 11 components, in type-parameter
// order. It is only returned by value; its fields are only valid as long as
// the pointers themselves are (see ViewN.Get and ViewN.Each).
type Components11[T1, T2, T3, T4, T5, T6, T7, T8, T9, T10, T11 any] struct {
	Comp1  *T1
	Comp2  *T2
	Comp3  *T3
	Comp4  *T4
	Comp5  *T5
	Comp6  *T6
	Comp7  *T7
	Comp8  *T8
	Comp9  *T9
	Comp10 *T10
	Comp11 *T11
}

// Unpack returns the pointers as separate values.
func (c Components11[T1, T2, T3, T4, T5, T6, T7, T8, T9, T10, T11]) Unpack() (*T1, *T2, *T3, *T4, *T5, *T6, *T7, *T8, *T9, *T10, *T11) {
	return c.Comp1, c.Comp2, c.Comp3, c.Comp4, c.Comp5, c.Comp6, c.Comp7, c.Comp8, c.Comp9, c.Comp10, c.Comp11
}

// NewEntity11 creates an entity holding exactly these 11 components,
// inferring the component types from the argument types. Registers each
// type on first use.
//
// Panics with "ecs: duplicate component: <type>" if two type parameters are
// the same type.
//
// Cost: 0 allocations in steady state.
func NewEntity11[T1, T2, T3, T4, T5, T6, T7, T8, T9, T10, T11 any](w *World, v1 T1, v2 T2, v3 T3, v4 T4, v5 T5, v6 T6, v7 T7, v8 T8, v9 T9, v10 T10, v11 T11) Entity {
	ids := [11]storage.CompID{
		storage.CompID(RegisterComp[T1]()),
		storage.CompID(RegisterComp[T2]()),
		storage.CompID(RegisterComp[T3]()),
		storage.CompID(RegisterComp[T4]()),
		storage.CompID(RegisterComp[T5]()),
		storage.CompID(RegisterComp[T6]()),
		storage.CompID(RegisterComp[T7]()),
		storage.CompID(RegisterComp[T8]()),
		storage.CompID(RegisterComp[T9]()),
		storage.CompID(RegisterComp[T10]()),
		storage.CompID(RegisterComp[T11]()),
	}
	arch := w.newEntityArchetype(ids[:])
	e, row := w.spawnIn(arch)
	columnOf[T1](arch, ids[0]).Set(row, v1)
	columnOf[T2](arch, ids[1]).Set(row, v2)
	columnOf[T3](arch, ids[2]).Set(row, v3)
	columnOf[T4](arch, ids[3]).Set(row, v4)
	columnOf[T5](arch, ids[4]).Set(row, v5)
	columnOf[T6](arch, ids[5]).Set(row, v6)
	columnOf[T7](arch, ids[6]).Set(row, v7)
	columnOf[T8](arch, ids[7]).Set(row, v8)
	columnOf[T9](arch, ids[8]).Set(row, v9)
	columnOf[T10](arch, ids[9]).Set(row, v10)
	columnOf[T11](arch, ids[10]).Set(row, v11)
	w.revision++
	return e
}

// NewView11 returns a view over every entity with all 11 of these
// component types. It registers and resolves the component IDs now; the
// archetype it spawns into (ViewN.NewEntity) and the archetype-match cache
// (ViewN.Each) are each resolved lazily, on first use. Filters such as
// [Without] narrow which entities Each and Has select; they are checked once
// per archetype, not per entity.
//
// Panics with "ecs: duplicate component: <type>" if two type parameters are
// the same type or two filters exclude the same type, with "ecs: component
// both required and excluded: <type>" if a filter excludes one of the type
// parameters, and with "ecs: zero Filter" for a Filter not made by Without.
func NewView11[T1, T2, T3, T4, T5, T6, T7, T8, T9, T10, T11 any](w *World, filters ...Filter) View11[T1, T2, T3, T4, T5, T6, T7, T8, T9, T10, T11] {
	ids := []storage.CompID{
		storage.CompID(RegisterComp[T1]()),
		storage.CompID(RegisterComp[T2]()),
		storage.CompID(RegisterComp[T3]()),
		storage.CompID(RegisterComp[T4]()),
		storage.CompID(RegisterComp[T5]()),
		storage.CompID(RegisterComp[T6]()),
		storage.CompID(RegisterComp[T7]()),
		storage.CompID(RegisterComp[T8]()),
		storage.CompID(RegisterComp[T9]()),
		storage.CompID(RegisterComp[T10]()),
		storage.CompID(RegisterComp[T11]()),
	}
	return View11[T1, T2, T3, T4, T5, T6, T7, T8, T9, T10, T11]{state: newViewState(w, ids, filters)}
}

// View11 is a reusable view over entities with these 11 fixed
